<script setup lang="ts">import {ref} from 'vue';import {Mail,KeyRound,ShieldCheck,Copy,Check} from 'lucide-vue-next';import PageHeader from '../components/PageHeader.vue';import ConfirmDialog from '../components/ConfirmDialog.vue';import {useVintro} from '../composables/useVintro';import {useSelectedVehicle} from '../composables/useSelectedVehicle';const {notify}=useVintro();const {vehicle,base}=useSelectedVehicle();const email=ref('');const dialog=ref(false);const mode=ref<'email'|'code'>('code');const code=ref('');const copied=ref(false);const open=(m:'email'|'code')=>{mode.value=m;dialog.value=true};const confirm=()=>{dialog.value=false;if(mode.value==='code'){code.value='VNT-82K4-MP3';notify('Transfer code generated')}else notify('Transfer invitation created')};const copy=async()=>{await navigator.clipboard.writeText(code.value);copied.value=true;notify('Code copied');setTimeout(()=>copied.value=false,1200)}

</script>
<template><PageHeader title="Transfer vehicle" :back="base"/><div class="container-app max-w-3xl py-7"><p class="eyebrow">Ownership</p><h1 class="page-title mt-2">Transfer vehicle</h1><p class="mt-3 max-w-xl leading-7 text-muted">Transfer the Vintro record to the vehicle's new owner. The service history stays with the car.</p><div class="card mt-8 flex items-center gap-4 p-4"><div class="h-16 w-24 overflow-hidden rounded-xl bg-stone-100"><img :src="vehicle.image" class="h-full w-full object-cover"/></div><div><p class="font-semibold">{{vehicle.make}} {{vehicle.model}}</p><p class="mt-1 text-sm text-muted">VIN ending {{vehicle.vin.slice(-4)}}</p></div></div><div class="mt-6 grid gap-4 md:grid-cols-2"><section class="card p-5"><span class="grid h-10 w-10 place-items-center rounded-xl bg-stone-100"><Mail :size="19"/></span><h2 class="mt-5 text-lg font-semibold">Invite new owner</h2><p class="mt-2 text-sm leading-6 text-muted">Create an invitation for the buyer's email address.</p><label class="mt-5 block"><span class="label">Email address</span><input v-model="email" type="email" class="field" placeholder="new.owner@example.com"/></label><button @click="open('email')" :disabled="!email.includes('@')" class="btn-primary mt-4 w-full">Send transfer invitation</button></section><section class="card p-5"><span class="grid h-10 w-10 place-items-center rounded-xl bg-stone-100"><KeyRound :size="19"/></span><h2 class="mt-5 text-lg font-semibold">Transfer code</h2><p class="mt-2 text-sm leading-6 text-muted">Generate a single-use code to share with the new owner.</p><div v-if="code" class="mt-5 flex items-center justify-between rounded-xl bg-stone-100 p-4"><strong class="nums tracking-[.12em]">{{code}}</strong><button @click="copy" class="grid h-9 w-9 place-items-center rounded-lg bg-white"><Check v-if="copied" :size="17" class="text-success"/><Copy v-else :size="17"/></button></div><button v-else @click="open('code')" class="btn-secondary mt-5 w-full">Generate transfer code</button></section></div><div class="mt-6 flex gap-3 rounded-2xl bg-emerald-50 p-5"><ShieldCheck class="shrink-0 text-success"/><p class="text-sm leading-6 text-muted"><strong class="block text-ink">What transfers</strong>The vehicle profile, specifications and verified maintenance history. Your personal information is not included.</p></div></div><ConfirmDialog :open="dialog" @close="dialog=false" @confirm="confirm"><h2 class="text-xl font-semibold">{{mode==='code'?'Generate transfer code?':'Create transfer invitation?'}}</h2><p class="mt-2 text-sm leading-6 text-muted">This prototype won't send or transfer anything. In the live product, you would confirm ownership before continuing.</p><template #confirm>{{mode==='code'?'Generate code':'Create invitation'}}</template></ConfirmDialog></template>
